class Bookings:
    def __init__(self, capacity):
        self.free = capacity
        self.holds = {}

    def reserve(self, key, seats):
        if type(seats) is not int or seats <= 0 or seats > self.free:
            raise ValueError("invalid seats")
        if key in self.holds:
            raise ValueError("duplicate booking")
        self.free -= seats
        self.holds[key] = seats
        return {"id": key, "seats": seats}

    def cancel(self, key):
        if key not in self.holds:
            return False
        self.free += self.holds.pop(key)
        return True


def caption(room):
    return "Room " + room.strip().upper()

